const features = await helpers.httpRequest({ method:'GET', url:'http://localhost:3000/api/issues?limit=2000' });
const items = Array.isArray(features) ? features : (features.issues || []);
const candidates = items.filter(i => i.type==='feature' && i.status==='open' && i.acceptance_criteria && i.description);
const gaps = [];
for (const f of candidates) {
  const hasChild = items.some(i => i.parent_id === f.id);
  if (!hasChild) gaps.push({ task_key: f.task_key, title: f.title, project: f.project, sprint: f.sprint });
}
return [{ json: { action: gaps.length ? 'gaps_found' : 'idle', count: gaps.length, gaps: gaps.slice(0,25) } }];
